function moyennePonderee(notes) {
  let sommeProduit = 0;
  let sommeCoeff = 0;
  for (const note of notes) {
    sommeProduit += note.valeur * note.coeff;
    sommeCoeff += note.coeff;
  }
  return sommeCoeff === 0 ? 0 : sommeProduit / sommeCoeff;
}

function frequenceMots(phrase) {
  const mots = phrase.split(/\s+/);
  const freqs = {};
  for (const mot of mots) {
    if (!mot) continue;
    freqs[mot] = (freqs[mot] || 0) + 1;
  }
  return freqs;
}

function transcrireADN(adn) {
